import os

from client.app import create_app


def main():
    """Executable 'chambeaya-client' entry point generated by Poetry."""
    create_app().run(
        host=os.getenv("CLIENT_HOST", "127.0.0.1"),
        port=int(os.getenv("CLIENT_PORT", "5001")),
    )


if __name__ == "__main__":
    main()
